import java.io.*;
import java.util.*;

import jakarta.servlet.*;
import jakarta.servlet.annotation.*;
import jakarta.servlet.http.*;
import com.bisangoding.web.*;

public class Main {
    public static void main(String[] args) {
        ServerUji server = new ServerUji();
        server.tambah(new TodoServlet());
        server.cetak("POST", "/todo", "judul=Belajar+Servlet");
        server.cetak("POST", "/todo", "judul=");
        server.cetak("GET", "/todo");
    }
