class DaftarTodo {
    static final List<String> data = new ArrayList<>();
}

@WebServlet("/todo")
class TodoServlet extends HttpServlet {
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse res) throws IOException {
        res.setContentType("text/plain;charset=UTF-8");
        PrintWriter out = res.getWriter();
        for (int i = 0; i < DaftarTodo.data.size(); i++) {
            out.println((i + 1) + ". " + DaftarTodo.data.get(i));
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse res) throws IOException {
        String judul = req.getParameter("judul");
        if (judul == null || judul.trim().isEmpty()) {
            res.sendError(400, "judul wajib diisi");
            return;
        }
        DaftarTodo.data.add(judul.trim());
        res.setStatus(201);
        res.setContentType("text/plain;charset=UTF-8");
        res.getWriter().print("Tersimpan: " + judul.trim());
    }
}

