import java.io.*;
import java.util.*;

import jakarta.servlet.*;
import jakarta.servlet.annotation.*;
import jakarta.servlet.http.*;
import com.bisangoding.web.*;

public class Main {
    public static void main(String[] args) {
        ServerUji server = new ServerUji();
        server.tambah(new ProdukServlet());
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            server.cetak("GET", in.nextLine());
        }
    }
}

@WebServlet("/produk/*")
class ProdukServlet extends HttpServlet {
    private final Map<String, Integer> harga = new TreeMap<>();

    @Override
    public void init() {
        harga.put("kopi", 18000);
        harga.put("teh", 8000);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse res) throws IOException {
        String nama = req.getPathInfo() == null ? "" : req.getPathInfo().substring(1);
        if (!harga.containsKey(nama)) {
            res.sendError(404, "produk " + nama + " tidak ada");
            return;
        }
        res.setContentType("text/plain;charset=UTF-8");
        res.getWriter().print(nama + ": " + harga.get(nama));
    }
}
